    interactive_config = coalesce(interactive_config, '{}'::jsonb) || jsonb_build_object('scenarios', $gfx6$[{"question": "A candle opens at 2,350.00 and closes at 2,354.00. It is…", "options": ["Bearish", "Bullish", "Neutral by definition", "Invalid"], "correctIndex": 1, "explanation": "It closed above its open, so it is a bullish candle."}, {"question": "High 2,356.00, Low 2,347.00. What is the candle's range?", "options": ["$4", "$6", "$9", "$11"], "correctIndex": 2, "explanation": "Range = high − low = 2,356.00 − 2,347.00 = $9.00."}, {"question": "What does a long upper wick usually show?", "options": ["Price never went higher than the body", "Buyers pushed price up but it was pushed back down before the close", "The market was closed", "A guaranteed reversal"], "correctIndex": 1, "explanation": "The wick shows price traded higher but did not hold there; it is information, not a guarantee."}]$gfx6$::jsonb),
