    interactive_config = coalesce(interactive_config, '{}'::jsonb) || jsonb_build_object('scenarios', $gfx6$[{"question": "What does a doji usually indicate?", "options": ["Strong guaranteed uptrend", "Indecision, with open and close nearly equal", "Market closed", "A broker error"], "correctIndex": 1, "explanation": "A doji has nearly equal open and close, suggesting indecision."}, {"question": "Which describes a hammer?", "options": ["Long upper wick after a rise", "Small body near the top with a long lower wick after a decline", "No wicks at all", "A huge red body"], "correctIndex": 1, "explanation": "A hammer has a long lower wick and small body near the top, usually after a decline."}, {"question": "In the hypothetical example, where is the stop loss placed?", "options": ["Above the high at 2,335.00", "Below the hammer's wick, around 2,325.00", "No stop loss needed", "At the entry price"], "correctIndex": 1, "explanation": "The stop goes below the wick so the trade closes at a planned loss if the pattern fails."}]$gfx6$::jsonb),
