    examples = $gfx6$[{"title": "A week-one demo routine", "steps": ["Hypothetical $1,000 demo account. Rule: max 1% risk ($10) per trade, stop loss always.", "Trade idea: buy XAUUSD at 2,350.00, stop 2,346.00 ($4.00 per oz). Size = $10 ÷ $4 = 2.5 oz → round down to 0.02 lot (2 oz, $8 risk).", "Journal entry: reason for entry, SL/TP levels, size, result, and a yes/no: 'Did I follow my plan?'", "At week's end, count rule-following trades, not the demo balance."], "note": "Convention note: GFX lessons treat a $0.01 move in XAUUSD as 1 pip, and 1 standard lot as 100 oz, so a $0.01 move = $1 per standard lot. Many brokers define a gold pip differently (often $0.10) and contract sizes can vary. Always check your own broker's contract specifications.", "hypothetical": true, "disclaimer": "All prices are illustrative and hypothetical, not real quotes, forecasts, or results."}]$gfx6$::jsonb,
    interactive_config = coalesce(interactive_config, '{}'::jsonb) || jsonb_build_object('scenarios', $gfx6$[{"question": "What is the best measure of demo progress?", "options": ["Highest demo balance", "Weeks of consistently following your plan", "Number of trades per day", "Biggest single win"], "correctIndex": 1, "explanation": "GFX measures readiness by process: weeks of following your rules, not profits."}, {"question": "Hypothetical: $1,000 demo, 1% risk, stop distance $4.00. Largest size within the rule (0.01-lot steps)?", "options": ["0.02 lot", "0.03 lot", "0.25 lot", "1 lot"], "correctIndex": 0, "explanation": "$10 ÷ $4 per oz = 2.5 oz; round DOWN to 0.02 lot (2 oz = $8 risk). 0.03 lot would risk $12, over 1%."}, {"question": "Why can demo results differ from live?", "options": ["Demo uses fake charts", "Demo fills can be smoother and there's no real emotional pressure", "Live accounts have no spreads", "They never differ"], "correctIndex": 1, "explanation": "Fills and emotions differ, which is why you treat demo money as real and start small if you ever go live."}]$gfx6$::jsonb),
    estimated_minutes = 6,
    updated_at = now()
where slug = 'demo-account-your-practice-ground'
