-- position-sizing-and-lot-calculation: QUIZ ADDITION (content unchanged). passing_score 67 = 2 of 3 correct (quiz uses round(score/n*100) >= passing_score)
update lessons
set interactive_config = coalesce(interactive_config, '{}'::jsonb) || jsonb_build_object('scenarios', $gfx6$[{"question": "Hypothetical: your demo account is $2,000. Under the GFX 1% rule, what is the most you may risk on one trade?", "options": ["$2", "$20", "$200", "$1,000"], "correctIndex": 1, "explanation": "1% of $2,000 = $20. That is the maximum planned loss if your stop loss is hit."}, {"question": "Hypothetical: you plan to buy XAUUSD at 2,350.00 with a stop loss at 2,343.50. What is the stop distance?", "options": ["$0.65 (65 pips)", "$6.50 (650 pips)", "$65.00 (6,500 pips)", "$3.50 (350 pips)"], "correctIndex": 1, "explanation": "2,350.00 − 2,343.50 = $6.50. With $0.01 = 1 pip, that is 650 pips. (Many brokers count a gold pip as $0.10, which would make it 65 pips; the dollar distance is the same.)"}, {"question": "Same trade: $20 max risk, $6.50 stop distance. With 1 lot = 100 oz (so 0.01 lot = 1 oz and a $0.01 move = $1 per lot), what is the largest lot size within the rule, in 0.01-lot steps?", "options": ["0.03 lot", "0.04 lot", "0.30 lot", "3 lots"], "correctIndex": 0, "explanation": "Loss per 0.01 lot = $6.50 × 1 oz = $6.50. $20 ÷ $6.50 ≈ 3.08 → round DOWN to 3 × 0.01 = 0.03 lot (risk $19.50). 0.04 lot would risk $26, which is over 1%."}]$gfx6$::jsonb),
    passing_score = 67,
    updated_at = now()
where slug = 'position-sizing-and-lot-calculation'
